macro_rules! deps {
    () => {
        RegionConstraintCollector!();
        LeakCheck!();
        CombinedSnapshot!();
        MiniGraph!();
    };
}

macro_rules! impl_112 {
    () => {
        deps!();
        impl < 'tcx > RegionConstraintCollector < '_ , 'tcx > { # [doc = " Searches new universes created during `snapshot`, looking for"] # [doc = " placeholders that may \"leak\" out from the universes they are contained"] # [doc = " in. If any leaking placeholders are found, then an `Err` is returned"] # [doc = " (typically leading to the snapshot being reversed). This algorithm"] # [doc = " only looks at placeholders which cannot be named by `outer_universe`,"] # [doc = " as this is the universe we're currently checking for a leak."] # [doc = ""] # [doc = " The leak check *used* to be the only way we had to handle higher-ranked"] # [doc = " obligations. Now that we have integrated universes into the region"] # [doc = " solvers, this is no longer the case, but we retain the leak check for"] # [doc = " backwards compatibility purposes. In particular, it lets us make \"early\""] # [doc = " decisions about whether a region error will be reported that are used in"] # [doc = " coherence and elsewhere -- see #56105 and #59490 for more details. The"] # [doc = " eventual fate of the leak checker is not yet settled."] # [doc = ""] # [doc = " The leak checker works by searching for the following error patterns:"] # [doc = ""] # [doc = " * P1: P2, where P1 != P2"] # [doc = " * P1: R, where R is in some universe that cannot name P1"] # [doc = ""] # [doc = " The idea here is that each of these patterns represents something that"] # [doc = " the region solver would eventually report as an error, so we can detect"] # [doc = " the error early. There is a fly in the ointment, though, in that this is"] # [doc = " not entirely true. In particular, in the future, we may extend the"] # [doc = " environment with implied bounds or other info about how placeholders"] # [doc = " relate to regions in outer universes. In that case, `P1: R` for example"] # [doc = " might become solvable."] # [doc = ""] # [doc = " # Summary of the implementation"] # [doc = ""] # [doc = " The leak checks as follows. First, we construct a graph where `R2: R1`"] # [doc = " implies `R2 -> R1`, and we compute the SCCs."] # [doc = ""] # [doc = " For each SCC S, we compute:"] # [doc = ""] # [doc = " * what placeholder P it must be equal to, if any"] # [doc = "   * if there are multiple placeholders that must be equal, report an error because `P1: P2`"] # [doc = " * the minimum universe of its constituents"] # [doc = ""] # [doc = " Then we walk the SCCs in dependency order and compute"] # [doc = ""] # [doc = " * what placeholder they must outlive transitively"] # [doc = "   * if they must also be equal to a placeholder, report an error because `P1: P2`"] # [doc = " * minimum universe U of all SCCs they must outlive"] # [doc = "   * if they must also be equal to a placeholder P, and U cannot name P, report an error, as"] # [doc = "     that indicates `P: R` and `R` is in an incompatible universe"] # [doc = ""] # [doc = " To improve performance and for the old trait solver caching to be sound, this takes"] # [doc = " an optional snapshot in which case we only look at region constraints added in that"] # [doc = " snapshot. If we were to not do that the `leak_check` during evaluation can rely on"] # [doc = " region constraints added outside of that evaluation. As that is not reflected in the"] # [doc = " cache key this would be unsound."] # [doc = ""] # [doc = " # Historical note"] # [doc = ""] # [doc = " Older variants of the leak check used to report errors for these"] # [doc = " patterns, but we no longer do:"] # [doc = ""] # [doc = " * R: P1, even if R cannot name P1, because R = 'static is a valid sol'n"] # [doc = " * R: P1, R: P2, as above"] # [instrument (level = "debug" , skip (self , tcx , only_consider_snapshot) , ret)] pub fn leak_check (self , tcx : TyCtxt < 'tcx > , outer_universe : ty :: UniverseIndex , max_universe : ty :: UniverseIndex , only_consider_snapshot : Option < & CombinedSnapshot < 'tcx > > ,) -> RelateResult < 'tcx , () > { if outer_universe == max_universe { return Ok (()) ; } let mini_graph = MiniGraph :: new (& self , only_consider_snapshot) ; let mut leak_check = LeakCheck :: new (tcx , outer_universe , max_universe , mini_graph , self) ; leak_check . assign_placeholder_values () ? ; leak_check . propagate_scc_value () ? ; Ok (()) } }
    };
}

impl_112!();